import { Routes, Route, Navigate } from 'react-router-dom';
import ProtectedRoute from './ProtectedRoute';
import MainLayout from '../layout/MainLayout';

import LoginPage from '../screens/LoginPage';
import RegisterPage from '../screens/RegisterPage';
import DashboardPage from '../screens/DashboardPage';
import ProfilePage from '../screens/ProfilePage';

import ComplaintsPage from '../screens/ComplaintsPage';
import NewComplaintPage from '../screens/NewComplaintPage';
import GatePassPage from '../screens/GatePassPage';
import NewGatePassPage from '../screens/NewGatePassPage';
import MessPage from '../screens/MessPage';
import FoodPage from '../screens/FoodPage';

export default function AppRoutes() {
  return (
    <Routes>
      <Route path="/login" element={<LoginPage />} />
      <Route path="/register" element={<RegisterPage />} />

      <Route
        element={
          <ProtectedRoute>
            <MainLayout />
          </ProtectedRoute>
        }
      >
        <Route path="/" element={<Navigate to="/dashboard" replace />} />
        <Route path="/dashboard" element={<DashboardPage />} />
        <Route path="/profile" element={<ProfilePage />} />

        <Route path="/complaints" element={<ComplaintsPage />} />
        <Route path="/complaints/new" element={<NewComplaintPage />} />

        <Route path="/gatepass" element={<GatePassPage />} />
        <Route path="/gatepass/new" element={<NewGatePassPage />} />

        <Route path="/mess" element={<MessPage />} />
        <Route path="/food" element={<FoodPage />} />
      </Route>
    </Routes>
  );
}
